INSERT INTO course_revisions (id, course_id, status, title, summary, difficulty, estimated_minutes, lesson_count, submitted_at, published_at, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e002-0000-7000-8000-200000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-100000000001'), 'PUBLISHED', 'SQL 2: Nối bảng', 'Kết hợp dữ liệu từ nhiều bảng qua khoá chính và khoá ngoại.\n- INNER JOIN và nối nhiều bảng liên tiếp\n- LEFT JOIN và tìm dòng không có cặp\n- Bẫy đặt điều kiện trong ON hay trong WHERE\n- RIGHT JOIN, FULL JOIN, SELF JOIN, CROSS JOIN\n- Nhận ra và tránh hiện tượng nhân dòng khi nối', 'EASY', 152, 13, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000')
INSERT INTO chapters (id, revision_id, title, position, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e002-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-200000000001'), 'Quan hệ giữa các bảng', 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e002-0000-7000-8000-200000000001'), 'INNER JOIN', 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e002-0000-7000-8000-200000000001'), 'OUTER JOIN', 3, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e002-0000-7000-8000-200000000001'), 'Nối đặc biệt', 4, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lessons (id, chapter_id, lesson_key, slug, title, body, position, estimated_minutes, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000001'), 'khoa-chinh-va-khoa-ngoai', 'Khoá chính, khoá ngoại và các kiểu quan hệ', '## Vì sao dữ liệu nằm ở nhiều bảng\n\nNếu mỗi đơn hàng lưu lại cả tên, thành phố của khách, thì khi khách đổi thành phố bạn phải sửa hàng chục dòng. Database quan hệ tránh điều này bằng cách lưu mỗi thông tin **một lần** ở đúng bảng của nó, rồi nối các bảng lại bằng khoá.\n\n## Khoá chính và khoá ngoại\n\n- **Khoá chính** định danh duy nhất một dòng: `customers.id`, `orders.id`.\n- **Khoá ngoại** là cột chứa khoá chính của bảng khác: `orders.customer_id` chứa `id` của một khách.\n\nKhi viết `orders.customer_id = customers.id`, bạn đang nói "đơn này thuộc khách này".\n\n## Ba kiểu quan hệ\n\n- **Một nhiều**: một khách có nhiều đơn, mỗi đơn thuộc một khách. Khoá ngoại nằm ở phía "nhiều" (`orders.customer_id`).\n- **Nhiều nhiều**: một đơn có nhiều sản phẩm, một sản phẩm nằm trong nhiều đơn. Cần **bảng trung gian** `order_items` chứa cả `order_id` và `product_id`.\n- **Tự tham chiếu**: bảng trỏ tới chính nó. `employees.manager_id` trỏ tới một nhân viên khác, `categories.parent_id` trỏ tới danh mục cha.\n\n## Sơ đồ database Cửa hàng\n\n```\ncustomers 1 ──── n orders 1 ──── n order_items n ──── 1 products n ──── 1 categories\n                                                                         │\nemployees.manager_id ──► employees.id          categories.parent_id ──► categories.id\n```\n\n## Thử ngay\n\nÔ dưới xem các dòng hàng của đơn số 1. Cột `product_id` chỉ là con số; bài tiếp theo sẽ nối sang bảng products để lấy tên.', 1, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000002'), 'vi-sao-can-join', 'Vì sao cần JOIN', '## Câu hỏi cần hai bảng\n\n> Đơn số 4 của khách nào, ở thành phố nào?\n\nBảng `orders` chỉ có `customer_id = 3`. Không có JOIN, bạn phải chạy hai truy vấn:\n\n```sql\nSELECT customer_id FROM orders WHERE id = 4;\n```\n\n```sql\nSELECT name, city FROM customers WHERE id = 3;\n```\n\nCách này ổn với một đơn, nhưng với "mọi đơn kèm tên khách" thì không khả thi.\n\n## JOIN ghép dòng theo điều kiện\n\nJOIN đặt hai bảng cạnh nhau và ghép mỗi dòng bên trái với các dòng bên phải thoả điều kiện `ON`:\n\n```sql\nSELECT orders.id, orders.order_date, customers.name, customers.city\nFROM orders\nJOIN customers ON customers.id = orders.customer_id;\n```\n\nKết quả có 30 dòng, mỗi đơn một dòng, kèm thông tin khách.\n\n## Hình dung bằng tay\n\nVới mỗi dòng của `orders`, database tìm trong `customers` dòng có `id` bằng `customer_id` của đơn đó, rồi dán hai dòng thành một. Một khách có 5 đơn sẽ xuất hiện 5 lần, mỗi lần đi kèm một đơn.\n\n## Thử ngay\n\nChạy ô dưới, rồi thử thêm điều kiện `WHERE customers.city = ''Hà Nội''` trước dấu chấm phẩy.', 2, 8, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000003'), 'inner-join-va-bi-danh-bang', 'INNER JOIN và bí danh bảng', '## INNER JOIN chỉ giữ cặp khớp nhau\n\n`JOIN` viết không kèm gì chính là `INNER JOIN`. Nó chỉ giữ các cặp dòng thoả điều kiện ON. Dòng nào không tìm được cặp sẽ **biến mất** khỏi kết quả.\n\n```sql\nSELECT products.name, categories.name\nFROM products\nINNER JOIN categories ON categories.id = products.category_id;\n```\n\nBảng products có 20 sản phẩm nhưng kết quả chỉ có 19 dòng: "Thẻ quà tặng" có `category_id` là NULL nên không khớp danh mục nào.\n\n## Bí danh bảng\n\nGõ lại tên bảng rất dài dòng. Đặt bí danh ngắn ngay sau tên bảng:\n\n```sql\nSELECT p.name AS product, c.name AS category, p.price\nFROM products p\nJOIN categories c ON c.id = p.category_id;\n```\n\n## Khi nào bắt buộc ghi tên bảng trước cột\n\nCả hai bảng đều có cột `name` và `id`. Nếu chỉ viết `name`, PostgreSQL báo lỗi "column reference is ambiguous". Quy tắc an toàn: trong truy vấn có JOIN, **luôn** ghi bí danh trước mọi cột.\n\n## Thứ tự hai bảng\n\nVới INNER JOIN, `A JOIN B` và `B JOIN A` cho cùng tập kết quả. Thứ tự chỉ quan trọng với LEFT và RIGHT JOIN ở chương sau.\n\n## Thử ngay\n\nÔ dưới liệt kê sản phẩm kèm danh mục, sắp theo danh mục. Thử bỏ bí danh trước cột name để thấy lỗi.', 1, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000004'), 'noi-nhieu-bang', 'Nối nhiều bảng liên tiếp', '## Đi theo chuỗi khoá\n\nCâu hỏi "khách nào mua sản phẩm gì" đi qua bốn bảng:\n\n```\ncustomers ─► orders ─► order_items ─► products\n```\n\nMỗi bước là một JOIN, nối bảng mới vào kết quả đã có:\n\n```sql\nSELECT c.name AS customer, o.id AS order_id, o.order_date, p.name AS product, oi.quantity\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nJOIN order_items oi ON oi.order_id = o.id\nJOIN products p ON p.id = oi.product_id\nORDER BY o.order_date, o.id;\n```\n\n## Mẹo viết JOIN dài\n\n1. Bắt đầu từ bảng "trung tâm" của câu hỏi.\n2. Mỗi JOIN, tự hỏi: bảng mới nối với bảng nào đã có, qua cột nào?\n3. Chạy thử sau mỗi JOIN thêm vào để chắc số dòng hợp lý.\n\n## Nối thêm danh mục\n\nThêm một bước nữa để biết mỗi sản phẩm đã bán thuộc danh mục nào:\n\n```sql\nSELECT o.id AS order_id, p.name AS product, cat.name AS category\nFROM orders o\nJOIN order_items oi ON oi.order_id = o.id\nJOIN products p ON p.id = oi.product_id\nJOIN categories cat ON cat.id = p.category_id;\n```\n\nĐể ý: dòng hàng "Thẻ quà tặng" của đơn 18 biến mất vì sản phẩm này không có danh mục. Mỗi INNER JOIN trong chuỗi đều có thể làm rơi dòng.\n\n## Thử ngay\n\nÔ dưới liệt kê sản phẩm mà khách ở Hồ Chí Minh đã mua. Thử thêm cột danh mục.', 2, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000002'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000005'), 'join-ket-hop-where', 'JOIN kết hợp WHERE, ORDER BY và tính toán', '## Lọc sau khi nối\n\nSau khi JOIN, bạn có thể lọc theo cột của **bất kỳ** bảng nào tham gia:\n\n```sql\nSELECT o.id, c.name, o.order_date, o.status\nFROM orders o\nJOIN customers c ON c.id = o.customer_id\nWHERE c.city = ''Hà Nội'' AND o.status = ''DELIVERED'';\n```\n\n## Tính toán trên cột của nhiều bảng\n\nSo sánh giá bán thực tế với giá niêm yết để tìm dòng hàng được giảm giá:\n\n```sql\nSELECT oi.order_id, p.name, p.price, oi.unit_price,\n       p.price - oi.unit_price AS discount\nFROM order_items oi\nJOIN products p ON p.id = oi.product_id\nWHERE oi.unit_price < p.price\nORDER BY discount DESC;\n```\n\n## Điều kiện nối không chỉ có dấu bằng\n\nON có thể chứa nhiều điều kiện hoặc so sánh khác `=`. Ví dụ ghép mỗi đơn với các sản phẩm có giá dưới 1 triệu xuất hiện trong chính đơn đó:\n\n```sql\nSELECT oi.order_id, p.name, p.price\nFROM order_items oi\nJOIN products p ON p.id = oi.product_id AND p.price < 1000000;\n```\n\nVới INNER JOIN, đặt điều kiện phụ trong ON hay trong WHERE cho cùng kết quả. Với LEFT JOIN thì khác hẳn, bạn sẽ thấy ở chương sau.\n\n## Thử ngay\n\nÔ dưới tìm các dòng hàng được giảm giá. Thử thêm tên khách bằng một JOIN nữa qua orders.', 3, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000006'), 'left-join', 'LEFT JOIN giữ mọi dòng bên trái', '## Vấn đề của INNER JOIN\n\nMuốn liệt kê **mọi khách hàng** kèm đơn của họ, INNER JOIN bỏ mất 3 khách chưa mua lần nào. `LEFT JOIN` giải quyết điều đó: mọi dòng của bảng bên trái được giữ, phần bên phải không khớp thì điền NULL.\n\n```sql\nSELECT c.name, o.id AS order_id, o.order_date\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nORDER BY c.id, o.order_date;\n```\n\nKết quả có 33 dòng: 30 đơn của 12 khách đã mua, cộng 3 dòng cho Mai Quân, Trịnh Sơn, Cao Thảo với `order_id` và `order_date` là NULL.\n\n## Bên trái là bảng nào\n\n"Bên trái" là bảng đứng **trước** từ khoá LEFT JOIN. Đổi chỗ hai bảng thì ý nghĩa đổi theo:\n\n```sql\nSELECT o.id, c.name\nFROM orders o\nLEFT JOIN customers c ON c.id = o.customer_id;\n```\n\nỞ đây mọi đơn đều có khách nên kết quả giống INNER JOIN.\n\n## Khi nào dùng LEFT JOIN\n\nKhi câu hỏi có chữ **mọi**, **tất cả**, **kể cả những ... chưa**: mọi khách kèm số đơn, tất cả sản phẩm kèm số lượng đã bán, kể cả sản phẩm chưa bán được.\n\n## Thử ngay\n\nÔ dưới liệt kê mọi sản phẩm kèm các đơn đã mua nó. Tìm hai sản phẩm có order_id là NULL.', 1, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000007'), 'tim-dong-khong-khop', 'Tìm dòng không có cặp', '## Mẫu anti join\n\nCâu hỏi kiểu "khách **chưa từng** đặt hàng" hay "sản phẩm **chưa** bán được" rất phổ biến. Mẫu giải: LEFT JOIN rồi giữ các dòng mà bên phải là NULL.\n\n```sql\nSELECT c.id, c.name\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.id IS NULL;\n```\n\nKết quả: Mai Quân, Trịnh Sơn, Cao Thảo.\n\n## Kiểm tra cột nào là NULL\n\nHãy kiểm tra **khoá chính** của bảng bên phải (`o.id`). Nếu kiểm tra một cột có thể NULL sẵn, bạn sẽ lấy nhầm các dòng có khớp nhưng cột đó trống.\n\n## Sản phẩm chưa bán\n\n```sql\nSELECT p.name, p.price\nFROM products p\nLEFT JOIN order_items oi ON oi.product_id = p.id\nWHERE oi.id IS NULL;\n```\n\nKết quả: Giày da và Bàn phím cơ.\n\n## Danh mục không có sản phẩm trực tiếp\n\n```sql\nSELECT cat.name\nFROM categories cat\nLEFT JOIN products p ON p.category_id = cat.id\nWHERE p.id IS NULL;\n```\n\nKết quả gồm Điện tử, Máy tính, Thời trang, Sách. Đây là các danh mục cha: sản phẩm nằm ở danh mục con của chúng. Ở chặng CTE bạn sẽ học cách lấy cả sản phẩm của danh mục con.\n\nChặng Truy vấn lồng sẽ giới thiệu thêm cách viết bằng `NOT EXISTS` cho cùng loại câu hỏi.\n\n## Thử ngay\n\nÔ dưới tìm nhân viên không quản lý ai. Gợi ý: nối employees với chính nó qua manager_id.', 2, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000008'), 'dieu-kien-on-va-where', 'Bẫy: điều kiện trong ON hay trong WHERE', '## Cùng một điều kiện, hai kết quả\n\nYêu cầu: liệt kê **mọi khách** kèm các đơn đã huỷ của họ (nếu có).\n\n**Cách 1**, điều kiện trong WHERE:\n\n```sql\nSELECT c.name, o.id AS cancelled_order\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.status = ''CANCELLED'';\n```\n\nChỉ còn 3 dòng. Các khách không có đơn huỷ đã biến mất.\n\n**Cách 2**, điều kiện trong ON:\n\n```sql\nSELECT c.name, o.id AS cancelled_order\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id AND o.status = ''CANCELLED'';\n```\n\nĐủ 15 khách, ai không có đơn huỷ thì `cancelled_order` là NULL. Đây mới là đáp án đúng.\n\n## Vì sao\n\n- Điều kiện trong **ON** quyết định dòng bên phải nào được ghép. Dòng bên trái luôn được giữ.\n- Điều kiện trong **WHERE** chạy **sau** khi nối. Dòng có `o.status` là NULL (khách không có đơn huỷ) không thoả `= ''CANCELLED''` nên bị loại, biến LEFT JOIN thành INNER JOIN.\n\n## Quy tắc\n\n- Điều kiện về **bảng bên phải** của LEFT JOIN: đặt trong ON.\n- Điều kiện về **bảng bên trái**: đặt trong WHERE.\n- Ngoại lệ: `WHERE b.id IS NULL` của mẫu anti join phải nằm ở WHERE.\n\n## Thử ngay\n\nChạy cả hai ô và so sánh số dòng.', 3, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000003'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000009'), 'right-join-va-full-join', 'RIGHT JOIN và FULL OUTER JOIN', '## RIGHT JOIN\n\n`A RIGHT JOIN B` giữ mọi dòng của **B**. Nó chính là `B LEFT JOIN A` viết ngược. Trên thực tế người ta gần như chỉ dùng LEFT JOIN cho dễ đọc: bảng chính luôn đứng đầu.\n\n```sql\nSELECT cat.name AS category, p.name AS product\nFROM products p\nRIGHT JOIN categories cat ON cat.id = p.category_id;\n```\n\n## FULL OUTER JOIN\n\n`FULL JOIN` giữ mọi dòng của **cả hai** bảng. Dòng không có cặp ở bên nào thì bên kia là NULL:\n\n```sql\nSELECT cat.name AS category, p.name AS product\nFROM products p\nFULL JOIN categories cat ON cat.id = p.category_id\nORDER BY cat.name NULLS FIRST, p.name;\n```\n\nKết quả có 24 dòng:\n\n- 19 cặp sản phẩm và danh mục khớp nhau.\n- 1 sản phẩm không có danh mục (Thẻ quà tặng), cột category là NULL.\n- 4 danh mục cha không có sản phẩm trực tiếp, cột product là NULL.\n\n## Khi nào dùng FULL JOIN\n\nĐối soát hai nguồn dữ liệu: danh sách hàng trong kho và danh sách trong hệ thống bán hàng, muốn thấy cả hàng có ở bên này mà thiếu ở bên kia. MySQL không hỗ trợ FULL JOIN; ở đó người ta ghép LEFT JOIN và RIGHT JOIN bằng UNION.\n\n## Thử ngay\n\nÔ dưới đếm số dòng của từng loại trong FULL JOIN. Thử đổi thành LEFT JOIN và RIGHT JOIN để so sánh.', 4, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000010'), 'self-join', 'SELF JOIN: nối bảng với chính nó', '## Nhân viên và quản lý\n\nBảng `employees` có `manager_id` trỏ tới `id` của một nhân viên khác. Để hiển thị tên quản lý, ta nối bảng với **chính nó**, mỗi lần dùng một bí danh khác nhau:\n\n```sql\nSELECT e.name AS employee, m.name AS manager\nFROM employees e\nJOIN employees m ON m.id = e.manager_id;\n```\n\nHãy hình dung có hai bản sao của bảng: `e` đóng vai nhân viên, `m` đóng vai quản lý.\n\n## Giữ cả người không có quản lý\n\nGiám đốc Trần Quang có `manager_id` là NULL nên biến mất với INNER JOIN. Dùng LEFT JOIN để giữ lại:\n\n```sql\nSELECT e.name AS employee, COALESCE(m.name, ''(không có)'') AS manager\nFROM employees e\nLEFT JOIN employees m ON m.id = e.manager_id\nORDER BY e.id;\n```\n\n## Danh mục và danh mục cha\n\nBảng `categories` cũng tự tham chiếu qua `parent_id`:\n\n```sql\nSELECT child.name AS category, parent.name AS parent_category\nFROM categories child\nLEFT JOIN categories parent ON parent.id = child.parent_id;\n```\n\n## Giới hạn của SELF JOIN\n\nMột SELF JOIN chỉ đi lên **một** cấp. Muốn biết cả quản lý của quản lý, bạn cần nối thêm một lần nữa, và không biết trước cây sâu bao nhiêu cấp. CTE đệ quy ở chặng 5 giải quyết đúng vấn đề này.\n\n## Thử ngay\n\nÔ dưới hiển thị nhân viên kèm quản lý và quản lý cấp trên nữa bằng hai lần nối.', 1, 14, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000011'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000011'), 'so-sanh-trong-self-join', 'So sánh dòng với dòng trong SELF JOIN', '## Nhân viên lương cao hơn quản lý\n\nSau khi nối, cột của nhân viên và của quản lý nằm cùng một dòng nên so sánh trực tiếp được:\n\n```sql\nSELECT e.name, e.salary, m.name AS manager, m.salary AS manager_salary\nFROM employees e\nJOIN employees m ON m.id = e.manager_id\nWHERE e.salary > m.salary;\n```\n\nKết quả: Quách Duy (19 triệu) lương cao hơn quản lý Nguyễn Mai (18 triệu).\n\n## Vào làm trước quản lý\n\n```sql\nSELECT e.name, e.hire_date, m.name AS manager, m.hire_date AS manager_hire_date\nFROM employees e\nJOIN employees m ON m.id = e.manager_id\nWHERE e.hire_date < m.hire_date;\n```\n\nPhạm Hùng vào làm từ 2018, trước cả giám đốc Trần Quang.\n\n## Ghép cặp trong cùng nhóm\n\nSELF JOIN còn dùng để tìm cặp dòng có chung đặc điểm, ví dụ các cặp đồng nghiệp cùng phòng, cùng mức lương:\n\n```sql\nSELECT a.name, b.name, a.department, a.salary\nFROM employees a\nJOIN employees b ON b.department = a.department\n               AND b.salary = a.salary\n               AND a.id < b.id;\n```\n\nĐiều kiện `a.id < b.id` rất quan trọng: thiếu nó, mỗi người sẽ tự ghép với chính mình và mỗi cặp xuất hiện hai lần (A với B, rồi B với A).\n\n## Thử ngay\n\nÔ dưới tìm các cặp khách ở cùng thành phố. Thử bỏ điều kiện a.id < b.id để thấy số dòng tăng.', 2, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000012'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000012'), 'cross-join', 'CROSS JOIN và tích Descartes', '## Ghép mọi dòng với mọi dòng\n\n`CROSS JOIN` không có điều kiện: mỗi dòng bên trái ghép với **mọi** dòng bên phải. Bảng 3 dòng nhân bảng 4 dòng cho 12 dòng.\n\n```sql\nSELECT DISTINCT o.status, c.city\nFROM (SELECT DISTINCT status FROM orders) o\nCROSS JOIN (SELECT DISTINCT city FROM customers WHERE city IS NOT NULL) c\nORDER BY o.status, c.city;\n```\n\n4 trạng thái nhân 6 thành phố cho 24 tổ hợp.\n\n## Khi nào hữu ích\n\n- Tạo **khung báo cáo** đủ mọi tổ hợp, rồi LEFT JOIN số liệu thật vào để ô không có dữ liệu hiện số 0 thay vì biến mất.\n- Sinh dữ liệu thử: mọi cỡ áo nhân mọi màu.\n\n## Nguy hiểm: quên điều kiện nối\n\nViết nhiều bảng sau FROM cách nhau bằng dấu phẩy mà quên WHERE chính là CROSS JOIN:\n\n```sql\nSELECT COUNT(*)\nFROM orders, order_items;\n```\n\n30 đơn nhân 41 dòng hàng ra 1.230 dòng vô nghĩa. Với bảng thật hàng triệu dòng, truy vấn này có thể làm treo database. Đây là lý do nên luôn viết `JOIN ... ON` tường minh thay cho dấu phẩy.\n\n## Thử ngay\n\nÔ dưới tạo bảng giá thử nghiệm: mỗi sản phẩm sách nhân ba mức giảm giá.', 3, 10, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-400000000013'), UUID_TO_BIN('01a1e002-0000-7000-8000-300000000004'), UUID_TO_BIN('01a1e002-0000-7000-8000-500000000013'), 'nhan-dong-khi-noi', 'Nhân dòng khi nối và cách đếm đúng', '## Nối một nhiều làm tăng số dòng\n\nMỗi khách có nhiều đơn, mỗi đơn có nhiều dòng hàng. Nối khách với dòng hàng làm khách xuất hiện **nhiều lần**:\n\n```sql\nSELECT c.name, o.id AS order_id, oi.product_id\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nJOIN order_items oi ON oi.order_id = o.id\nWHERE c.id = 1;\n```\n\nNguyễn An có 5 đơn nhưng 7 dòng kết quả, vì đơn số 1 và đơn số 3 đều có hai dòng hàng.\n\n## Hệ quả khi đếm và cộng\n\nNếu bạn đếm số đơn sau khi đã nối tới `order_items`, đơn có nhiều dòng hàng sẽ bị đếm nhiều lần. Đây là lỗi rất hay gặp trong báo cáo, gọi là **fan out**.\n\nCách đúng tuỳ câu hỏi:\n\n- Đếm đơn: dùng `COUNT(DISTINCT o.id)` (học ở chặng Gom nhóm), hoặc đừng nối tới order_items.\n- Cộng tiền theo đơn: tính trên `order_items` rồi mới nối lên.\n\n## Tự kiểm tra trước khi tin kết quả\n\nSau mỗi JOIN, hãy tự hỏi: **mỗi dòng của kết quả đại diện cho cái gì?** Một đơn, một dòng hàng, hay một khách? Nếu không trả lời được, kết quả gần như chắc chắn sai.\n\n## Tổng kết chặng Nối bảng\n\n- INNER JOIN: chỉ cặp khớp nhau.\n- LEFT JOIN: giữ mọi dòng bên trái, mẫu `IS NULL` để tìm dòng không có cặp.\n- Điều kiện của bảng phải trong LEFT JOIN: đặt trong ON.\n- SELF JOIN: hai bí danh cho cùng một bảng.\n- CROSS JOIN: mọi tổ hợp, cẩn thận bùng nổ số dòng.\n\nChặng tiếp theo, **SQL 3: Gom nhóm**, sẽ dùng JOIN cùng COUNT, SUM để làm báo cáo thật.\n\n## Thử ngay\n\nÔ dưới cho thấy mỗi dòng là một dòng hàng. Thử đổi sang đếm số đơn khác nhau của từng khách bằng DISTINCT.', 4, 12, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO lesson_cells (id, lesson_id, cell_key, position, starter_sql, dialect, dataset_version_id, dataset_variant_id, dataset_checksum, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000001'), 1, 'SELECT id, order_id, product_id, quantity, unit_price\nFROM order_items\nWHERE order_id = 1;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000002'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000002'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000002'), 1, 'SELECT orders.id, orders.order_date, customers.name, customers.city\nFROM orders\nJOIN customers ON customers.id = orders.customer_id;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000003'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000003'), 1, 'SELECT p.name AS product, c.name AS category, p.price\nFROM products p\nJOIN categories c ON c.id = p.category_id\nORDER BY c.name, p.price DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000004'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000004'), 1, 'SELECT c.name AS customer, o.order_date, p.name AS product, oi.quantity\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nJOIN order_items oi ON oi.order_id = o.id\nJOIN products p ON p.id = oi.product_id\nWHERE c.city = ''Hồ Chí Minh''\nORDER BY o.order_date;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000005'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000005'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000005'), 1, 'SELECT oi.order_id, p.name, p.price, oi.unit_price,\n       p.price - oi.unit_price AS discount\nFROM order_items oi\nJOIN products p ON p.id = oi.product_id\nWHERE oi.unit_price < p.price\nORDER BY discount DESC;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000006'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000006'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000006'), 1, 'SELECT p.name, oi.order_id, oi.quantity\nFROM products p\nLEFT JOIN order_items oi ON oi.product_id = p.id\nORDER BY p.id;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000007'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000007'), 1, 'SELECT e.name, e.department\nFROM employees e\nLEFT JOIN employees report ON report.manager_id = e.id\nWHERE report.id IS NULL;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000008'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000007'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000008'), 2, 'SELECT p.name, p.price\nFROM products p\nLEFT JOIN order_items oi ON oi.product_id = p.id\nWHERE oi.id IS NULL;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000009'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000009'), 1, 'SELECT c.name, o.id AS cancelled_order\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id\nWHERE o.status = ''CANCELLED'';', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000010'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000008'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000010'), 2, 'SELECT c.name, o.id AS cancelled_order\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id AND o.status = ''CANCELLED''\nORDER BY c.id;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000011'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000009'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000011'), 1, 'SELECT cat.name AS category, p.name AS product\nFROM products p\nFULL JOIN categories cat ON cat.id = p.category_id\nWHERE p.id IS NULL OR cat.id IS NULL;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000012'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000010'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000012'), 1, 'SELECT e.name AS employee, m.name AS manager, mm.name AS manager_of_manager\nFROM employees e\nLEFT JOIN employees m ON m.id = e.manager_id\nLEFT JOIN employees mm ON mm.id = m.manager_id\nORDER BY e.id;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000013'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000011'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000013'), 1, 'SELECT a.name, b.name, a.city\nFROM customers a\nJOIN customers b ON b.city = a.city AND a.id < b.id\nORDER BY a.city, a.name;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000014'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000012'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000014'), 1, 'SELECT p.name, d.percent, p.price * (100 - d.percent) / 100 AS sale_price\nFROM products p\nCROSS JOIN (VALUES (5), (10), (20)) AS d(percent)\nWHERE p.category_id IN (11, 12)\nORDER BY p.name, d.percent;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-600000000015'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000013'), UUID_TO_BIN('01a1e002-0000-7000-8000-700000000015'), 1, 'SELECT c.name, o.id AS order_id, p.name AS product, oi.quantity\nFROM customers c\nJOIN orders o ON o.customer_id = c.id\nJOIN order_items oi ON oi.order_id = o.id\nJOIN products p ON p.id = oi.product_id\nWHERE c.id = 1\nORDER BY o.id;', 'POSTGRESQL', UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d02'), UUID_TO_BIN('01a1e000-0000-7000-8000-000000000d03'), 'b9e493a8886c9ecb9e24ba075d73d685c07d83fba6f75b1a8906f609f317d58b', '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000');
INSERT INTO quiz_questions (id, lesson_id, question_key, prompt, is_multiple, position, created_at, updated_at) VALUES
    (UUID_TO_BIN('01a1e002-0000-7000-8000-800000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-900000000001'), 'Quan hệ giữa orders và products là kiểu gì?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
    (UUID_TO_BIN('01a1e002-0000-7000-8000-800000000002'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000001'), UUID_TO_BIN('01a1e002-0000-7000-8000-900000000002'), 'Trong quan hệ một khách nhiều đơn, khoá ngoại nằm ở bảng nào?', FALSE, 2, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
