    (UUID_TO_BIN('01a1e002-0000-7000-8000-800000000005'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000003'), UUID_TO_BIN('01a1e002-0000-7000-8000-900000000005'), 'Vì sao ''Thẻ quà tặng'' không có trong kết quả INNER JOIN products với categories?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
