    (UUID_TO_BIN('01a1e002-0000-7000-8000-800000000007'), UUID_TO_BIN('01a1e002-0000-7000-8000-400000000004'), UUID_TO_BIN('01a1e002-0000-7000-8000-900000000007'), 'Để biết khách nào mua sản phẩm nào, cần đi qua những bảng nào?', FALSE, 1, '2026-11-26 00:00:00.000000', '2026-11-26 00:00:00.000000'),
